package net.civeira.phylax.features.access.consentpurpose.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.tenant.domain.TenantReference;

class ConsentPurposeChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_consent_purpose_change_set_builder() {
    ConsentPurposeChangeSet one = new ConsentPurposeChangeSet()
        .uid("one").tenant(TenantReference.of("one")).key(ConsentPurposeKeyOptions.MARKETING)
        .title("one").description("one").required(true).activationDate(LocalDateTime
            .of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(TenantReference.of("one"), one.getTenant().get(),
        "Value must equals to the intial value");
    one.tenant(TenantReference.of("two"));
    Assertions.assertEquals(TenantReference.of("two"), one.getTenant().get(),
        "Value must equals to the assigned value");
    one.unset("tenant");
    Assertions.assertFalse(one.getTenant().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ConsentPurposeKeyOptions.MARKETING, one.getKey().get(),
        "Value must equals to the intial value");
    one.key(ConsentPurposeKeyOptions.ANALYTICS);
    Assertions.assertEquals(ConsentPurposeKeyOptions.ANALYTICS, one.getKey().get(),
        "Value must equals to the assigned value");
    one.unset("key");
    Assertions.assertFalse(one.getKey().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getTitle().get(), "Value must equals to the intial value");
    one.title("two");
    Assertions.assertEquals("two", one.getTitle().get(), "Value must equals to the assigned value");
    one.unset("title");
    Assertions.assertFalse(one.getTitle().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getDescription().get(),
        "Value must equals to the intial value");
    one.description("two");
    Assertions.assertEquals("two", one.getDescription().get(),
        "Value must equals to the assigned value");
    one.unset("description");
    Assertions.assertFalse(one.getDescription().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getRequired().get(), "Value must equals to the intial value");
    one.required(false);
    Assertions.assertEquals(false, one.getRequired().get(),
        "Value must equals to the assigned value");
    one.unset("required");
    Assertions.assertFalse(one.getRequired().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getActivationDate().get(), "Value must equals to the intial value");
    one.activationDate(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getActivationDate().get(), "Value must equals to the assigned value");
    one.unset("activationDate");
    Assertions.assertFalse(one.getActivationDate().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
